import json
d=json.load(open('visual-report/results.json'))
def find(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if 'style' in k.lower(): print(p+k, json.dumps(v)[:1500])
            find(v,p+k+'.')
    elif isinstance(o,list):
        for i,v in enumerate(o): find(v,p+str(i)+'.')
find(d)
E

